.COLUMN_NO, 1, length(A.COLUMN_NO) - 1)) D ON A.COLUMN = D.COLUMN --不同钢种 LEFT JOIN(SELECT SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1) AS COLUMN, COUNT(1) AS D_SG_SIGN_NUM FROM TWM04 A LEFT JOIN(SELECT B.MAT_NO, C.STOCK_PLACE_NO, B.SG_SIGN FROM TWMA1 B, TWMA2 C LEFT JOIN TWMA7 E ON E.MAT_NO = C.MAT_NO WHERE C.MAT_NO = B.MAT_NO AND C.STOCK_NO = 'C01') D ON A.STOCK_PLACE_NO = D.STOCK_PLACE_NO WHERE A.STOCK_NO = '' AND STOCK_PLACE_TYPE = '0' AND D.SG_SIGN != '' GROUP BY SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1) ORDER BY SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1)) E ON A.COLUMN = E.COLUMN --同用户 LEFT JOIN(SELECT SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1) AS COLUMN, COUNT(1) AS ORDER_CUST_CODE_NUM FROM TWM04 A LEFT JOIN(SELECT B.MAT_NO, C.STOCK_PLACE_NO, B.ORDER_CUST_CODE FROM TWMA1 B, TWMA2 C LEFT JOIN TWMA7 E ON E.MAT_NO = C.MAT_NO WHERE C.MAT_NO = B.MAT_NO AND C.STOCK_NO = 'C01') D ON A.STOCK_PLACE_NO = D.STOCK_PLACE_NO WHERE A.STOCK_NO = '' AND STOCK_PLACE_TYPE = '0' AND D.ORDER_CUST_CODE = '' GROUP BY SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1) ORDER BY SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1)) F ON A.COLUMN = F.COLUMN --不同用户 LEFT JOIN(SELECT SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1) AS COLUMN, COUNT(1) AS D_ORDER_CUST_CODE_NUM FROM TWM04 A LEFT JOIN(SELECT B.MAT_NO, C.STOCK_PLACE_NO, B.ORDER_CUST_CODE FROM TWMA1 B, TWMA2 C LEFT JOIN TWMA7 E ON E.MAT_NO = C.MAT_NO WHERE C.MAT_NO = B.MAT_NO AND C.STOCK_NO = 'C01') D ON A.STOCK_PLACE_NO = D.STOCK_PLACE_NO WHERE A.STOCK_NO = '' AND STOCK_PLACE_TYPE = '0' AND D.ORDER_CUST_CODE != '' GROUP BY SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1) ORDER BY SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1)) G ON A.COLUMN = G.COLUMN --空跺位数 LEFT JOIN( SELECT DISTINCT SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1) AS COLUMN, COUNT(1) AS EMPTY_STOCK FROM TWM04 A WHERE A.STOCK_NO = '' AND STOCK_PLACE_TYPE = '0' AND STOCK_STATUS = '0' GROUP BY SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1) ORDER BY SUBSTR(A.COLUMN_NO, 1, length(A.COLUMN_NO) - 1)) H ON A.COLUMN = H.COLUMN;

